                      .and({
                        logic: () => obsStaff.Role === 1,
                        description: "obsStaff.Role=1",
                      })
                      .or({
                        logic: () => obsRepair.Process === 1,
                        description: "obsRepair.Process=1",
                      })
                      .and({
                        logic: () => obsStaff.Role === 2,
                        description: "obsStaff.Role=2",
                      })
                      .or({
                        logic: () => obsRepair.Process === 2,
